contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // run attempts to have the owner (this contract, the deployer of C) call sendMoney on c
    // target is any address, value is amount of wei to forward, data is calldata for the call
    function run(address target, uint value, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // ensure this test contract has the Ether needed to fund the sendMoney call
        require(address(this).balance >= value);

        // observe before-values
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // perform the state-changing call as the owner; must be a top-level statement
        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // General rule:
        // - If the call reverted: depositsCount and contract balance are unchanged.
        // - If the call succeeded: depositsCount is unchanged and contract balance decreased by exactly value.
        assert(
            (reverted && countAfter == countBefore && balAfter == balBefore) ||
            (!reverted && countAfter == countBefore && balBefore >= value && balAfter == balBefore - value)
        );
    }

    // accept refunds/transfers if c sends Ether back to this contract
    receive() external payable {}
}

